VIDEO_EXTENSIONS = ("mp4", "webm", "avi")
PDF_EXTENSIONS = ("pdf",)


def _file_type_for(extension):
    if extension in VIDEO_EXTENSIONS:
        return "video"
    if extension in PDF_EXTENSIONS:
        return "pdf"
    return "audio"


def convert_courses_to_lessons(apps, schema_editor):
    """Give every legacy single-file course a first lesson.

    Course.file and Course.video_url are left untouched for backward
    compatibility; the lesson only references a copy of the file.
    """
    Course = apps.get_model("courses", "Course")
    Lesson = apps.get_model("courses", "Lesson")

    for course in Course.objects.all().iterator():
        if Lesson.objects.filter(course_id=course.pk).exists():
            continue
        if not course.file and not course.video_url:
            continue

        lesson = Lesson(
            course_id=course.pk,
            title=course.title[:200],
            description=course.description or "",
            order=1,
            duration_minutes=None,
            is_published=True,
        )

        if course.file:
            extension = Path(course.file.name).suffix.lower().lstrip(".")
            lesson.file_type = _file_type_for(extension)
            try:
                with course.file.storage.open(course.file.name, "rb") as source:
                    lesson.file.save(
                        f"{uuid.uuid4().hex}.{extension}" if extension else uuid.uuid4().hex,
                        ContentFile(source.read()),
                        save=False,
                    )
            except (FileNotFoundError, OSError):
                # Media may be missing in some environments; keep the
                # reference so the lesson still exists.
                lesson.file.name = course.file.name
        else:
            lesson.video_url = course.video_url
            lesson.file_type = "video"

        lesson.save()


